import { useCallback, useEffect, useRef } from 'react'
import { InnerForm } from '../../../../../../../components'
import { getSeaForm } from '../../constants'
import { SeaFormStyle } from './index.style'
import { useGetShipMaterial } from '../../../../state/hooks/useMarineCargo'
import { resetError, useErrorContextValue, useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../../components/ShowNotification'

function SeaForm (props) {
  const { handleGetSubmitMethods, preFormData } = props

  const seaFormRef = useRef('')

  const [{ GET_SHIP_MATERIAL_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ getShipMaterialData = [] }, getShipMaterialRequest] = useGetShipMaterial()
  const [
    {
      GET_SHIP_MATERIAL_ERROR, getShipMaterialStatus
    },
    dispatchError
  ] = useErrorContextValue()

  const seaForm = getSeaForm(getShipMaterialData, preFormData)

  useEffect(() => {
    if (GET_SHIP_MATERIAL_LOADER === undefined) {
      getShipMaterialRequest()
    }
  }, [getShipMaterialRequest, GET_SHIP_MATERIAL_LOADER])

  useEffect(() => {
    if (GET_SHIP_MATERIAL_ERROR && getShipMaterialStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getShipMaterialStatus
      })
      dispatchError(resetError({
        getShipMaterialStatus: ''
      }))
    }
  }, [GET_SHIP_MATERIAL_ERROR, getShipMaterialStatus,
    dispatchError
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_SHIP_MATERIAL_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleSubmit = useCallback(async (e) => {
    const responseSeaForm = await seaFormRef.current.handleSubmit(e)
    if (responseSeaForm && Object.keys(responseSeaForm).length > 0) {
      return {
        ...responseSeaForm
      }
    }
  }, [])

  useEffect(() => {
    handleGetSubmitMethods('sea', handleSubmit)
  }, [handleGetSubmitMethods, handleSubmit])

  return (
    <SeaFormStyle>
      <InnerForm
        formData={seaForm}
        ref={seaFormRef}
      />
      <ShowSnackbar hideOkay />
    </SeaFormStyle>
  )
}

export default SeaForm
