import { useCallback, useEffect, useRef } from 'react'
import { InnerForm } from '../../../../../../../components'
import { getAirForm } from '../../constants'
import { AirFormStyle } from './index.style'

function AirForm (props) {
  const { handleGetSubmitMethods, preFormData } = props

  const airForm = getAirForm(preFormData)
  const airFormRef = useRef('')
  const sendSubmitRef = useRef(true)

  const handleSubmit = useCallback(async (e) => {
    const responseAirForm = await airFormRef.current.handleSubmit(e)
    if (responseAirForm && Object.keys(responseAirForm).length > 0) {
      return {
        ...responseAirForm
      }
    }
  }, [])

  useEffect(() => {
    if (sendSubmitRef.current) {
      handleGetSubmitMethods('air', handleSubmit)
      sendSubmitRef.current = false
    }
  }, [handleGetSubmitMethods, handleSubmit])

  return (
    <AirFormStyle>
      <InnerForm
        formData={airForm}
        ref={airFormRef}
      />
    </AirFormStyle>
  )
}

export default AirForm
