export const getShipManufacturingYears = () => {
  const currentYear = moment().year()
  const last40years = []
  let i = 0
  while (i < 40) {
    last40years.push({
      key: currentYear - i,
      value: currentYear - i
    })
    i++
  }
  return last40years
}

