import { RequiredStar, Row } from '../../../../../../../commonStyle/index.style'
import { CustomText, InnerForm, InnerInput } from '../../../../../../../components'
import AutoSearchModal from '../../../../../../../components/AutoSearchModal'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { getLandForm } from '../../constants'
import { LandFormStyle } from './index.style'
import { useCallback, useEffect, useRef, useState } from 'react'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../../../lang'
import { typeValid } from '../../../../../../../helpers/validations'
import { KARGO_LANG } from '../../../../lang'
import isEmpty from 'lodash/isEmpty'
import { useGetRegionCodes } from '../../../../state/hooks/useMarineCargo'
import { resetError, useErrorContextValue, updateLoader, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import { get } from 'lodash'

function LandForm (props) {
  const { handleGetSubmitMethods, preFormData } = props

  const landForm = getLandForm(preFormData)
  const [errorPlateNo, setErrorPlateNo] = useState('')
  const [regionCode, setRegionCode] = useState(get(preFormData, 'region_code'))
  const [vehiclePlateNo, setVehiclePlateNo] = useState(get(preFormData, 'vehicle_plate_no'))
  const vehicleTypeSumInsuredRef = useRef('')

  const [{ GET_REGION_CODES_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ getRegionCodesData = [] }, getRegionCodesRequest] = useGetRegionCodes()
  const [
    {
      GET_REGION_CODES_ERROR, getRegionCodesStatus
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (GET_REGION_CODES_LOADER === undefined) {
      getRegionCodesRequest()
    }
  }, [getRegionCodesRequest, GET_REGION_CODES_LOADER])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_REGION_CODES_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  useEffect(() => {
    if (GET_REGION_CODES_ERROR && getRegionCodesStatus) {
      ShowSnackbar.error({
        visible: true,
        text: getRegionCodesStatus
      })
      dispatchError(resetError({
        getRegionCodesStatus: ''
      }))
    }
  }, [GET_REGION_CODES_ERROR, getRegionCodesStatus,
    dispatchError
  ])

  const handlePlateNoChange = useCallback((e) => {
    setVehiclePlateNo(e.target.value)
    setErrorPlateNo(false)
  }, [])

  const handleSubmit = useCallback(async (e) => {
    const errorObj = {}

    if (regionCode === '' || vehiclePlateNo === '') {
      errorObj.errorPlateNo = LANG_STRINGS.required
    }

    if (!typeValid('plate_no', vehiclePlateNo)) {
      errorObj.errorPlateNo = ERROR_LANG.incorrectFormat
    }

    const responseVS = await vehicleTypeSumInsuredRef.current.handleSubmit(e)

    if (!isEmpty(errorObj)) {
      setErrorPlateNo(errorObj.errorPlateNo)
      return
    }

    if (responseVS && Object.keys(responseVS).length > 0) {
      return {
        ...responseVS,
        region_code: regionCode,
        vehicle_plate_no: vehiclePlateNo
      }
    }
  }, [regionCode, vehiclePlateNo])

  useEffect(() => {
    handleGetSubmitMethods('land', handleSubmit)
  }, [handleGetSubmitMethods, handleSubmit])

  return (
    <LandFormStyle>
      <InnerForm
        formData={landForm}
        ref={vehicleTypeSumInsuredRef}
      />
      <div className='row-space-between'>
        <CustomText
          size='12px'
          color={AgentColorPallette.fontSecondary}
          top='4px'
          bottom='4px'
        >
          {LANG_STRINGS.policeNumber}
          <RequiredStar>*</RequiredStar>
        </CustomText>
        <CustomText
          size='12px'
          color={AgentColorPallette.errorDark}
          top='4px'
          bottom='4px'
        >
          {errorPlateNo}
        </CustomText>
      </div>
      <Row align='center' justify='space-between'>
        <AutoSearchModal
          errorField={regionCode === '' && errorPlateNo ? 'region_code' : ''}
          data={getRegionCodesData}
          name='region_code'
          title={LANG_STRINGS.selectCode}
          id='auto_suggest_codes'
          displayKey='region_code'
          dataKey='region_code'
          defaultValue={get(preFormData, 'region_code', '')}
          placeholder={KARGO_LANG.regionalCode}
          onSelect={(value) => setRegionCode(value)}
          className='auto-search-codes'
        />
        <InnerInput
          errorField={(vehiclePlateNo === '' || !typeValid('plate_no', vehiclePlateNo)) && errorPlateNo ? 'vehicle_plate_no' : ''}
          name='vehicle_plate_no'
          value={vehiclePlateNo}
          placeholder='0000ABC'
          defaultValue=''
          onChange={handlePlateNoChange}
          className='plate-number-input'
        />
      </Row>
      <ShowSnackbar hideOkay />
    </LandFormStyle>
  )
}

export default LandForm
