import { Container, CustomText } from '../../../../../../components'
import AutoSearchModal from '../../../../../../components/AutoSearchModal'
import StepsHeader from '../../../../../../components/StepsHeader'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { KARGO_LANG } from '../../../lang'
import { useCallback, useState, useRef, useEffect, useMemo } from 'react'
import { BasicDetailsStyle } from './index.style'
import { LANG_STRINGS } from '../../../../../../lang'
import { MODES_OF_TRANSPORT } from '../constants'
import LandForm from '../components/LandForm'
import SeaForm from '../components/SeaForm'
import AirForm from '../components/AirForm'
import { DisplayFlexRCC } from '../../../../../../commonStyle/index.style'
import { getFromLocalStorageData, removeFromLocalStorageData, setToLocalStorage } from '../../../../../../helpers/localstorage'
import { MARINE_CARGO_BASIC_DETAILS_FORM } from '../../../constants'
import get from 'lodash/get'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import { SEND_GOLD_ICON } from '../../../../../../images'

function BasicDetailsContainer (props) {
  const landFormSubmit = useRef()
  const airFormSubmit = useRef()
  const seaFormSubmit = useRef()

  const preFormData = useMemo(() => (getFromLocalStorageData(MARINE_CARGO_BASIC_DETAILS_FORM) || {}), [])
  const [modeOfTransport, setModeOfTransport] = useState(get(preFormData, 'transportation_type') || '')

  useEffect(() => {
    removeFromLocalStorageData(MARINE_CARGO_BASIC_DETAILS_FORM)
  }, [])

  const handleSubmit = useCallback(async (e) => {
    let response = {}
    switch (modeOfTransport) {
      case 'land':
        response = await landFormSubmit.current(e)
        break
      case 'air':
        response = await airFormSubmit.current(e)
        break
      case 'sea':
        response = await seaFormSubmit.current(e)
        break
      default:
        break
    }
    if (response) {
      delete response.errorField

      setToLocalStorage(MARINE_CARGO_BASIC_DETAILS_FORM, {
        transportation_type: modeOfTransport,
        ...response
      })

      props.history.push({
        pathname: '/marine_cargo/packages'
      })
    }
  }, [modeOfTransport, props.history])

  const handleGetSubmitMethods = useCallback((formType, submitMethod) => {
    switch (formType) {
      case 'land':
        landFormSubmit.current = submitMethod
        break
      case 'air':
        airFormSubmit.current = submitMethod
        break
      case 'sea':
        seaFormSubmit.current = submitMethod
        break
      default:
        break
    }
  }, [])

  const renderTransportForm = useCallback(() => {
    switch (modeOfTransport) {
      case 'land':
        return (
          <LandForm
            preFormData={preFormData}
            handleGetSubmitMethods={handleGetSubmitMethods}
          />)
      case 'air':
        return (
          <AirForm
            preFormData={preFormData}
            handleGetSubmitMethods={handleGetSubmitMethods}
          />
        )
      case 'sea':
        return (
          <SeaForm
            preFormData={preFormData}
            handleGetSubmitMethods={handleGetSubmitMethods}
          />
        )
      default:
    }
  }, [modeOfTransport, handleGetSubmitMethods,
    preFormData
  ])

  return (
    <Container
      title='Kargo'
      hideBottomTabs
      displayBackButton
      backBtnId='kargoStepBack_1'
    >
      <BasicDetailsStyle>
        <StepsHeader leftText='Pengecekan Data' current='1' totalSteps='4' />
        <div className='content'>
          <CustomText
            color={AgentColorPallette.regular}
            lineHeight={1.5}
            size='13px'
            weight={500}
          >
            {KARGO_LANG.completeFormBelowForInsuranceOptions}
          </CustomText>
          <div className='form'>
            <CustomText
              size='10px'
              color={AgentColorPallette.black}
              bottom='5px'
            >
              {LANG_STRINGS.modeOfTransport}
            </CustomText>
            <AutoSearchModal
              errorField=''
              data={MODES_OF_TRANSPORT}
              placeholder={LANG_STRINGS.select}
              name='modeOfTransport'
              displayKey='value'
              defaultValue={modeOfTransport}
              value={modeOfTransport}
              dataKey='key'
              title={LANG_STRINGS.modeOfTransport}
              displayBorder
              onSelect={value => setModeOfTransport(value)}
            />
          </div>
          {
            renderTransportForm()
          }
        </div>
        <div className='bottom-action-container'>
          <DisplayFlexRCC className='bottom-continue-btn'>
            <ButtonWithIcon
              id='cargoStepSubmit_1'
              className='start-btn'
              text={LANG_STRINGS.next}
              icon={SEND_GOLD_ICON}
              iconRight
              disabled={!modeOfTransport}
              onClick={handleSubmit}
            />
          </DisplayFlexRCC>
        </div>
      </BasicDetailsStyle>
    </Container>
  )
}

export default BasicDetailsContainer
